import {once} from 'node:events';
import {askOnOpen, connectClient, framesUntil, startEngine, stopEngines} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {SessionStore} from '../types/sessionStore.js';

// A store that answers from a database cannot answer in the same tick, so the handler must wait without dropping a frame.

const CREATE_MS = 50;
// A hang fails in this long instead of stalling the suite; its tests stay on one line so a spec citation can name them.
const FAIL_FAST_MS = 5_000;
const wait = (ms: number) => new Promise<void>(resolve => setTimeout(resolve, ms));

// Wraps the real store so only the timing of `create` differs from the shipped one.
const slowStore = (delayMs: number, failWith?: Error): SessionStore => {
  const store = new InMemorySessionStore();
  return Object.assign(Object.create(Object.getPrototypeOf(store) as object) as SessionStore, store, {
    create: async (sessionId: string, userId: string | number) => {
      await wait(delayMs);
      if (failWith) throw failWith;
      return store.create(sessionId, userId);
    },
    get: (sessionId: string) => store.get(sessionId),
    delete: (sessionId: string) => store.delete(sessionId),
    count: () => store.count(),
    clear: () => store.clear(),
  }) as SessionStore;
};

describe('awaiting a slow session store', () => {
  afterEach(stopEngines);

  // prettier-ignore
  it('delivers a frame sent before the connected frame arrives', async () => {
    const url = await startEngine(slowStore(CREATE_MS));
    const {finished} = askOnOpen(url);

    const seen = await finished;

    expect(seen[0]).toBe('connected');
  }, FAIL_FAST_MS);
### 5.6 error

Reports an error condition. The connection remains open unless the error is fatal.

```json
{
  "type": "error",
  "code": "INVALID_MESSAGE",
  "message": "Message content cannot be empty"
}
```

| Field     | Type   | Description              |
| --------- | ------ | ------------------------ |
| `type`    | string | `"error"`                |
| `code`    | string | Machine-readable code    |
| `message` | string | Human-readable detail    |

Defined error codes:

| Code              | Description                                                       |
| ----------------- | ----------------------------------------------------------------- |
| `INVALID_MESSAGE` | Message failed validation (missing fields, empty content, length) |
| `INVALID_FORMAT`  | Message body is not valid JSON                                    |
| `RATE_LIMITED`    | AI provider returned a rate limit error                           |
| `SERVER_ERROR`    | Unexpected server error during message processing                 |

Semantics:

- A message the server cannot parse into a known type is answered with `INVALID_MESSAGE`, and no message stream is started for it ([validated by: rejects an unparseable message and never starts a stream](../../src/transport/ws/messageHandler.test.ts#L71)).
- A rate limit reported by the AI provider is surfaced as `RATE_LIMITED`, which tells the client the same request is worth retrying ([validated by: tells the client to retry when the provider is rate limited](../../src/transport/ws/messageHandler.test.ts#L311)).
- Any other failure raised while processing a message is reported as `SERVER_ERROR` ([validated by: reports any other failure as a server error](../../src/transport/ws/messageHandler.test.ts#L320)).

